function estado() {
  try { return 'listo'; }
  finally { console.log('limpieza'); }
}
console.log(estado());

function persistir(recurso, guardar) {
  try { return guardar(); }
  catch (error) { recurso.cerrar(); throw error; }
}

function ejecutar(falla) {
  const recurso = { cerrado: false };
  try {
    if (falla) throw new Error('fallo');
    return recurso;
  } catch (error) {
    recurso.cerrado = true;
    throw error;
  }
}
